create table MB_CCY_RATE (RATE_TYPE VARCHAR(10) not null  ,CCY VARCHAR(3) not null  ,BRANCH VARCHAR(30) not null  ,COUNTRY VARCHAR(3) null  ,QUOTE_TYPE VARCHAR(1) null  ,EXCH_BUY_RATE DECIMAL(15,8) null  ,EXCH_SELL_RATE DECIMAL(15,8) null  ,MIDDLE_RATE DECIMAL(15,8) null  ,NOTES_BUY_RATE DECIMAL(15,8) null  ,NOTES_SELL_RATE DECIMAL(15,8) null  ,MAX_FLOAT_RATE_UP DECIMAL(15,8) null  ,MAX_FLOAT_RATE_DOWN DECIMAL(15,8) null  ,CENTRAL_BANK_RATE DECIMAL(15,8) null  ,EFFECT_DATE TIMESTAMP(3) not null  ,EFFECT_TIME VARCHAR(6) not null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  , primary key(RATE_TYPE,CCY,BRANCH,EFFECT_DATE,EFFECT_TIME));